import XCTest
final class ProbeTests:XCTestCase {
 func tap(_ app:XCUIApplication,_ name:String){let matches=app.buttons.matching(identifier:name);XCTAssertTrue(matches.firstMatch.waitForExistence(timeout:10),app.debugDescription);guard let visible=matches.allElementsBoundByIndex.first(where:{$0.isHittable})else{XCTFail("No hittable button: "+name);return};visible.tap()}
 func testF44ConfirmBlockDirectReadonlyAndSharedGroupUnchanged() throws {
  continueAfterFailure=false
  let app=XCUIApplication(bundleIdentifier:"com.example.fancy.dev");app.launch();let decline=app.buttons["Decline analytics"];if decline.waitForExistence(timeout:3){decline.tap()};tap(app,"Meals, tab, 2 of 5");app.otherElements["Past"].tap();let meal=app.buttons.matching(NSPredicate(format:"label BEGINSWITH %@","F44 shared table,")).firstMatch;XCTAssertTrue(meal.waitForExistence(timeout:12),app.debugDescription);meal.tap();tap(app,"Your host, F44 Host");let block=app.buttons["Block F44 Host"];XCTAssertTrue(block.waitForExistence(timeout:12),app.debugDescription);block.tap();XCTAssertTrue(app.buttons["Confirm block"].waitForExistence(timeout:5));tap(app,"Confirm block");XCTAssertTrue(app.staticTexts["Member blocked. Private contact is disabled. Shared groups are unchanged."].firstMatch.waitForExistence(timeout:10),app.debugDescription);XCTAssertTrue(app.buttons["Unblock F44 Host"].exists);print("QA_NATIVE_F44_BLOCK_CONFIRMED\n"+app.debugDescription);let a=XCTAttachment(screenshot:app.screenshot());a.name="native-f44-block-confirmed";a.lifetime = .keepAlways;add(a)
  tap(app,"Back");tap(app,"Back");tap(app,"Inbox, tab, 4 of 5");let direct=app.buttons.matching(NSPredicate(format:"label BEGINSWITH %@","F44 Host")).firstMatch;XCTAssertTrue(direct.waitForExistence(timeout:10),app.debugDescription);direct.tap();XCTAssertTrue(app.staticTexts["Synthetic host message before block."].firstMatch.waitForExistence(timeout:10),app.debugDescription);XCTAssertTrue(app.staticTexts["Synthetic guest reply before block."].firstMatch.exists);XCTAssertFalse(app.textViews.matching(NSPredicate(format:"label BEGINSWITH %@","Message")).firstMatch.exists);let b=XCTAttachment(screenshot:app.screenshot());b.name="native-f44-block-direct-readonly";b.lifetime = .keepAlways;add(b);tap(app,"Back")
  let group=app.buttons.matching(NSPredicate(format:"label BEGINSWITH %@","F44 shared table")).firstMatch;XCTAssertTrue(group.waitForExistence(timeout:10),app.debugDescription);group.tap();XCTAssertTrue(app.staticTexts["Synthetic shared group stays available."].firstMatch.waitForExistence(timeout:10),app.debugDescription);let input=app.textViews.matching(NSPredicate(format:"label BEGINSWITH %@","Message")).firstMatch;XCTAssertTrue(input.exists && input.isEnabled);print("QA_NATIVE_F44_SHARED_GROUP_UNCHANGED\n"+app.debugDescription);let c=XCTAttachment(screenshot:app.screenshot());c.name="native-f44-shared-group-unchanged";c.lifetime = .keepAlways;add(c);tap(app,"Back")
 }
}
